#!/usr/bin/env python3
"""Public synthetic A/B/C vectors generated by the actual .20 wheel."""
import base64
from copy import deepcopy
import hashlib
import json
import math
from pathlib import Path
from types import SimpleNamespace
import numpy as np
from no5_sonard.processing_m1 import max_pool_resample
from no5_sonard.protocol import pack_echogram_frame, unpack_echogram_frame
from no5_sonard_openecho.noise_reduction import NoiseReduction
from no5_sonard_openecho.echogram_context import pack_context


def make(output):
    root=Path(__file__).resolve().parents[1]
    old=json.loads((root/'tests/fixtures/impulse-interface-0417.json').read_text())
    base=next(c for c in old['cases'] if c['name']=='impulse_auto')
    raw=np.frombuffer(base64.b64decode(base['raw_adc_base64']),dtype='<u2').copy()
    raw[:334]=4095;raw.setflags(write=False);digest=hashlib.sha256(raw.tobytes()).hexdigest()
    cases=[]
    for index,stage in enumerate(['reference','mask_only','early_exclusion'],1):
        c=deepcopy(base);row=c['published_ping'];row.update(display_generation=index,noise_revision=index)
        reducer=NoiseReduction(near_field_m=.5 if stage=='early_exclusion' else 0.,revision=index)
        values,status=reducer.process(raw,ping_id=row['ping_id'],sample_period_ns=2000,
            tx_zero_sample_index=0,acquisition_source='own',blocks=[SimpleNamespace(**b) for b in c['blocks']])
        if stage=='mask_only':values[:334]=0
        amplitudes=max_pool_resample(values,start_index=0,bins=1024)
        if stage!='reference':amplitudes[:math.ceil(.5/row['display_window']['display_range_m']*1023)]=0
        header,_=unpack_echogram_frame(base64.b64decode(c['frame_base64']))
        frame=pack_echogram_frame(ping_id=header.ping_id,time_utc_ns=header.time_utc_ns,
            max_depth_m=header.displayed_max_depth_m,bottom_depth_m=header.bottom_depth_m,
            bottom_confidence=header.bottom_confidence,flags=header.flags,amplitudes=amplitudes)
        row['noise_active']=status['active'];context=pack_context(frame,row,selected_source='own',publication_sequence=index)
        from no5_sonard_openecho.echogram_context import unpack_context
        metadata,_=unpack_context(context)
        c.update(name=stage,raw_adc_base64=base64.b64encode(raw.tobytes()).decode(),
            raw_adc_sha256=digest,derived_adc_base64=base64.b64encode(values.tobytes()).decode(),
            frame_base64=base64.b64encode(frame).decode(),frame_sha256=hashlib.sha256(frame).hexdigest(),
            context_base64=base64.b64encode(context).decode(),context_sha256=hashlib.sha256(context).hexdigest(),
            context_metadata=metadata,display_mask_only_m=.5 if stage=='mask_only' else 0.,
            noise_reduction={'schema':'no5.sonard-noise-reduction-status/1','policy':reducer.policy(),
                             'latest':status,'display_generation':index})
        cases.append(c)
    assert hashlib.sha256(raw.tobytes()).hexdigest()==digest
    value={'schema':'no5.near-field-contract-fixture/1','host_version':'0.4.20',
        'synthetic':True,'raw_samples_modified':False,'cases':cases}
    output.write_text(json.dumps(value,indent=2)+'\n')
    return {'cases':len(cases),'sha256':hashlib.sha256(output.read_bytes()).hexdigest()}


if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True)
    print(json.dumps(make(p.parse_args().output)))
